package com.deepnote.service;
import com.deepnote.ai.OllamaEmbeddingClient; import com.deepnote.db.Database; import com.deepnote.model.Note; import java.sql.*; import java.time.Instant; import java.util.*;
public final class NoteIndexService {
 private final Database db; private final OllamaEmbeddingClient embedder; private final TextChunker chunker;
 public NoteIndexService(Database db,OllamaEmbeddingClient e,TextChunker c){this.db=db;embedder=e;chunker=c;}
 public void index(Note note) throws Exception {String hash=HashUtil.sha256(note.content());List<String> chunks=chunker.split(note.content());try(Connection c=db.open()){c.setAutoCommit(false);try{UUID id=findOrCreate(c,note,hash);if(alreadyIndexed(c,id,hash)){c.rollback();return;}List<List<Float>> vectors=new ArrayList<>();for(String chunk:chunks)vectors.add(embedder.embed(chunk));try(PreparedStatement d=c.prepareStatement("DELETE FROM note_chunks WHERE note_id=?")){d.setObject(1,id);d.executeUpdate();}try(PreparedStatement i=c.prepareStatement("INSERT INTO note_chunks(chunk_id,note_id,chunk_index,chunk_text,embedding) VALUES(?,?,?,?,?::vector)")){for(int n=0;n<chunks.size();n++){i.setObject(1,UUID.randomUUID());i.setObject(2,id);i.setInt(3,n);i.setString(4,chunks.get(n));i.setString(5,vectors.get(n).toString());i.addBatch();}i.executeBatch();}try(PreparedStatement u=c.prepareStatement("UPDATE notes SET indexed_content_hash=?,updated_at=CURRENT_TIMESTAMP,last_indexed_at=CURRENT_TIMESTAMP WHERE note_id=?")){u.setString(1,hash);u.setObject(2,id);u.executeUpdate();}c.commit();}catch(Exception x){c.rollback();throw x;}}}
 private UUID findOrCreate(Connection c,Note n,String hash)throws SQLException{try(PreparedStatement q=c.prepareStatement("SELECT note_id FROM notes WHERE file_path=?")){q.setString(1,n.path().toAbsolutePath().toString());try(ResultSet r=q.executeQuery()){if(r.next())return(UUID)r.getObject(1);}}UUID id=UUID.randomUUID();try(PreparedStatement i=c.prepareStatement("INSERT INTO notes(note_id,title,file_path,indexed_content_hash) VALUES(?,?,?,NULL)")){i.setObject(1,id);i.setString(2,n.title());i.setString(3,n.path().toAbsolutePath().toString());i.executeUpdate();}return id;}
 private boolean alreadyIndexed(Connection c,UUID id,String hash)throws SQLException{try(PreparedStatement q=c.prepareStatement("SELECT indexed_content_hash FROM notes WHERE note_id=?")){q.setObject(1,id);try(ResultSet r=q.executeQuery()){return r.next()&&hash.equals(r.getString(1));}}}
}
